#!/bin/sh
# Writes bridge/.env with fresh random tokens. Never overwrites an existing one.
set -eu
cd "$(dirname "$0")/.."
if [ -f .env ]; then
  echo ".env already exists; leaving it alone"
  exit 0
fi
token() { openssl rand -hex 32; }
cat > .env <<EOF
# Generated by scripts/init.sh. Secrets: never commit this file.
WA_AS_TOKEN=$(token)
WA_HS_TOKEN=$(token)
WA_PROVISIONING_SECRET=$(token)
FB_AS_TOKEN=$(token)
FB_HS_TOKEN=$(token)
FB_PROVISIONING_SECRET=$(token)
# Set to http://messenger:29319 when running --profile messenger.
MESSENGER_URL=
ADAPTER_AS_TOKEN=$(token)
ADAPTER_HS_TOKEN=$(token)
# Shared with the Convex deployment (npx convex env set BRIDGE_SECRET ...).
BRIDGE_SECRET=$(token)
# The Convex deployment's HTTP actions URL (https://<deployment>.convex.site).
CONVEX_SITE_URL=${CONVEX_SITE_URL:-http://host.docker.internal:3211}
ADAPTER_PORT=8080
EOF
chmod 600 .env
echo "wrote $(pwd)/.env"
